package cn.sifangguan.hotelaios.finance;

import cn.sifangguan.hotelaios.shared.context.TenantPrincipal;
import org.springframework.jdbc.core.namedparam.NamedParameterJdbcTemplate;
import java.util.*;

/** SQL branches of the single financial queue. Never paginates/counts separate first pages. */
public final class FinancePendingV2 {
 private FinancePendingV2(){}
 private static boolean has(TenantPrincipal p,String code){return p.hasPermission("*")||p.hasPermission(code);}
 private static boolean table(NamedParameterJdbcTemplate jdbc,String name){return Boolean.TRUE.equals(jdbc.queryForObject("select to_regclass(:name) is not null",Map.of("name","public."+name),Boolean.class));}
 private static String scope(String alias,String column){return "(:tenantScope or "+alias+"."+column+" in (:scopeIds))";}
 /** Match original-source read gates before exposing an archive approval as actionable. A grant is not source authorization. */
 private static String archiveSource(String type,String id,TenantPrincipal p,boolean delegated,boolean extended){
  boolean read=has(p,"finance.read"),review=has(p,"finance.review"),own=has(p,"finance.submit"),pay=has(p,"finance.pay");
  String deputy=delegated?" or exists(select 1 from fd_route dr where dr.tenant_id=d.tenant_id and dr.source_kind=%s and dr.source_id=d.id and fd_current_reviewer(dr.tenant_id,dr.source_kind,dr.source_id,dr.node,dr.original_id)=:actorId)":"";
  String claim="exists(select 1 from finance_claim d where d.tenant_id=:tenantId and d.id="+id+" and "+scope("d","hotel_id")+" and ("+read+" or ("+own+" and d.applicant_id=:actorId) or ("+pay+" and d.status='APPROVED' and d.cashier_account_id=:actorId) or ("+review+" and (:actorId in(d.manager_account_id,d.finance_account_id,d.director_account_id,d.leader_account_id)"+(delegated?deputy.formatted("'CLAIM'"):"")+"))))";
  String operation="exists(select 1 from fo_document d where d.tenant_id=:tenantId and d.id="+id+" and "+scope("d","hotel_id")+" and (d.type<>'PAYROLL' or :payroll) and (d.type<>'TAX_TASK' or :tax) and ("+read+" or ("+own+" and d.applicant_id=:actorId) or ("+pay+" and d.cashier_account_id=:actorId) or ("+review+" and (d.approval_route @> jsonb_build_array(cast(:actorId as text))"+(delegated?deputy.formatted("'OPERATION'"):"")+"))))";
  boolean ledger=read||has(p,"finance.configure")||has(p,"finance.accounting.read")||has(p,"finance.accounting.write")||has(p,"finance.accounting.review")||has(p,"finance.accounting.post")||has(p,"finance.accounting.close");
  String voucher="exists(select 1 from fa_voucher v join fa_book b on b.tenant_id=v.tenant_id and b.id=v.book_id where v.tenant_id=:tenantId and v.id="+id+" and "+ledger+" and "+scope("b","hotel_id")+" and (:payroll or not exists(select 1 from fa_source_event e where e.tenant_id=v.tenant_id and e.voucher_id=v.id and (upper(e.source_type) like '%PAYROLL%' or upper(coalesce(e.metadata->>'sourceType','')) like '%PAYROLL%'))))";
  String more="";
  if(extended){
   boolean accountRead=has(p,"finance.accounting.read"),sourceReader=read||accountRead;
   boolean supplyEntry=sourceReader||review||own||pay||has(p,"finance.accounting.write");
   String supply="exists(select 1 from fs_recognition source_rec join procurement_receipt source_receipt on source_receipt.tenant_id=source_rec.tenant_id and source_receipt.id=source_rec.receipt_id join procurement_order source_order on source_order.tenant_id=source_receipt.tenant_id and source_order.id=source_receipt.order_id where source_rec.tenant_id=:tenantId and source_rec.id="+id+" and source_receipt.status='APPROVED' and "+scope("source_order","hotel_id")+" and "+supplyEntry+" and ("+sourceReader+" or :actorId in(source_order.applicant_id,source_receipt.receiver_id,source_receipt.reviewer_id,source_rec.applicant_id,source_rec.cashier_id,source_rec.confirmer_id)))";
   String asset="exists(select 1 from fs_asset_card source_card where source_card.tenant_id=:tenantId and source_card.id="+id+" and "+scope("source_card","hotel_id")+" and "+sourceReader+")";
   String gain="exists(select 1 from fs_asset_gain source_gain where source_gain.tenant_id=:tenantId and source_gain.id="+id+" and "+scope("source_gain","hotel_id")+" and "+sourceReader+")";
   String accrual="exists(select 1 from far_plan source_plan where source_plan.tenant_id=:tenantId and source_plan.id="+id+" and "+scope("source_plan","hotel_id")+" and "+(sourceReader||review)+" and ("+sourceReader+" or source_plan.created_by=:actorId or exists(select 1 from far_revision source_revision where source_revision.tenant_id=source_plan.tenant_id and source_revision.plan_id=source_plan.id and source_revision.reviewer_id=:actorId)) and (exists(select 1 from fo_document source_document where source_document.tenant_id=source_plan.tenant_id and source_document.id=source_plan.source_document_id and source_document.status='APPROVED' and source_document.hotel_id=source_plan.hotel_id and source_document.company_id=source_plan.company_id) or exists(select 1 from fm_subledger source_opening where source_opening.tenant_id=source_plan.tenant_id and source_opening.id=source_plan.opening_subledger_id and source_opening.book_id=source_plan.book_id and source_opening.kind='PREPAID' and source_opening.status='ACTIVE')))";
   String bookReport="exists(select 1 from fac_report_source source_report join fa_book source_book on source_book.tenant_id=source_report.tenant_id and source_book.id=source_report.book_id join fa_period source_period on source_period.tenant_id=source_report.tenant_id and source_period.book_id=source_report.book_id and source_period.month=source_report.month where source_report.tenant_id=:tenantId and source_report.id="+id+" and "+scope("source_book","hotel_id")+" and "+ledger+" and (:payroll or not source_report.sensitive_payroll) and source_period.close_snapshot is not null)";
   String intake="exists(select 1 from finance_invoice_intake source_intake where source_intake.tenant_id=:tenantId and source_intake.id="+id+" and (("+own+" and source_intake.owner_id=:actorId) or ("+read+" and "+scope("source_intake","hotel_id")+")))";
   boolean procurementRead=has(p,"procurement.read"),procurementConfigure=has(p,"procurement.configure"),procurementEntry=procurementRead||procurementConfigure||has(p,"procurement.request");
   String procurement="exists(select 1 from procurement_order source_procurement where source_procurement.tenant_id=:tenantId and source_procurement.id="+id+" and "+scope("source_procurement","hotel_id")+" and "+procurementEntry+" and ("+(procurementRead||procurementConfigure)+" or source_procurement.applicant_id=:actorId))";
   more=" or "+type+"='SUPPLY_RECOGNITION' and "+supply+" or "+type+"='ASSET_CARD' and "+asset+" or "+type+"='ASSET_GAIN' and "+gain+" or "+type+"='ACCRUAL' and "+accrual+" or "+type+"='BOOK_REPORT' and "+bookReport+" or "+type+"='INTAKE' and "+intake+" or "+type+"='PROCUREMENT' and "+procurement;
  }
  return "("+type+"='CLAIM' and "+claim+" or "+type+"='OPERATION' and "+operation+" or "+type+"='VOUCHER' and "+voucher+" or "+type+"='PAYROLL' and :payroll or "+type+"='TAX_RETURN' and :tax or "+type+" in ('REVENUE','INTERCOMPANY') and "+(read||review)+" or "+type+"='INSIGHT' and "+(read||has(p,"finance.accounting.read")||has(p,"finance.configure"))+" or "+type+"='MIGRATION' and "+has(p,"finance.configure")+more+")";
 }
 public static String unionSql(NamedParameterJdbcTemplate jdbc,TenantPrincipal p){var sql=new StringBuilder();boolean config=has(p,"finance.configure"),financialRead=config||has(p,"finance.read")||has(p,"finance.accounting.read");
  if(table(jdbc,"fb_revenue_batch"))sql.append("""
   union all select d.id,'review','收入来源待独立确认 · '||d.channel,h.name,u.display_name,d.control_total,d.status,d.business_date,d.created_at,false,d.version,'FINANCE_BUSINESS','REVENUE'
    from fb_revenue_batch d join org_unit h on h.tenant_id=d.tenant_id and h.id=d.hotel_id join user_account u on u.tenant_id=d.tenant_id and u.id=d.created_by
    where d.tenant_id=:tenantId and :review and d.status='REVIEW' and d.reviewer_id=:actorId and d.created_by<>:actorId and
   """).append(scope("d","hotel_id"));
  if(table(jdbc,"fb_payroll_batch"))sql.append("""
   union all select d.id,'review','工资表待独立确认 · '||to_char(d.month,'YYYY-MM'),h.name,u.display_name,d.net_amount,d.status,d.month,d.created_at,false,d.version,'FINANCE_BUSINESS','PAYROLL'
    from fb_payroll_batch d join org_unit h on h.tenant_id=d.tenant_id and h.id=d.hotel_id join user_account u on u.tenant_id=d.tenant_id and u.id=d.created_by
    where d.tenant_id=:tenantId and :review and :payroll and d.status='REVIEW' and d.reviewer_id=:actorId and d.created_by<>:actorId and
   """).append(scope("d","hotel_id"));
  if(table(jdbc,"fb_intercompany")){for(boolean counter:List.of(false,true)){String hotel=counter?"counterparty_hotel_id":"hotel_id",reviewer=counter?"counterparty_reviewer_id":"reviewer_id",confirmed=counter?"counterparty_confirmed_by":"confirmed_by";sql.append(" union all select d.id,'review','内部往来待本方确认',h.name,u.display_name,d.amount,d.status,d.month,d.created_at,false,d.version,'FINANCE_BUSINESS','INTERCOMPANY' from fb_intercompany d join org_unit h on h.tenant_id=d.tenant_id and h.id=d.").append(hotel).append(" join user_account u on u.tenant_id=d.tenant_id and u.id=d.creator_id where d.tenant_id=:tenantId and :review and d.status='REVIEW' and d.creator_id<>:actorId and d.").append(reviewer).append("=:actorId and d.").append(confirmed).append(" is null and ").append(scope("d",hotel));}}
  if(table(jdbc,"far_revision"))sql.append("""
   union all select p.id,'review','租赁/摊销版本待总监确认 · '||p.title,h.name,u.display_name,r.total_basis,r.status,r.effective_month,r.created_at,false,r.version,'ACCRUAL','REVISION'
    from far_revision r join far_plan p on p.tenant_id=r.tenant_id and p.id=r.plan_id
    join org_unit h on h.tenant_id=p.tenant_id and h.id=p.hotel_id join user_account u on u.tenant_id=r.tenant_id and u.id=r.applicant_id
    where r.tenant_id=:tenantId and :review and r.status='PENDING' and r.reviewer_id=:actorId and r.applicant_id<>:actorId and
   """).append(scope("p","hotel_id"));
  if(table(jdbc,"far_schedule_issue"))sql.append("""
   union all select p.id,'work','租赁/待摊自动检查待处理 · '||p.title,h.name,u.display_name,null::numeric,'PENDING',
    min(i.month),min(i.updated_at),false,p.version+sum(i.attempts),'ACCRUAL','ATTENTION'
    from far_schedule_issue i join far_plan p on p.tenant_id=i.tenant_id and p.id=i.plan_id
    join finance_store_config c on c.tenant_id=p.tenant_id and c.hotel_id=p.hotel_id and c.company_id=p.company_id
    join org_unit h on h.tenant_id=p.tenant_id and h.id=p.hotel_id join user_account u on u.tenant_id=p.tenant_id and u.id=p.created_by
    where i.tenant_id=:tenantId and :review and i.status='PENDING' and c.enabled and c.workflow_version=2
     and :actorId in(c.finance_account_id,c.director_account_id)
     and not exists(select 1 from far_revision revision where revision.tenant_id=p.tenant_id and revision.plan_id=p.id and revision.status='PENDING')
     and
   """).append(scope("p","hotel_id")).append(" group by p.id,h.name,u.display_name ");
  if(table(jdbc,"fi_report")&&financialRead)sql.append("""
   union all select r.id,'review',case when r.status='DRAFT' then '财务月报待独立复核 · ' else '财务月报待发布 · ' end||r.title,
    coalesce((select string_agg(h.name,'、' order by h.name) from org_unit h where h.tenant_id=r.tenant_id and h.id=any(s.hotel_ids)),''),u.display_name,null::numeric,r.status,null::date,r.created_at,false,r.version,'INSIGHT',case when r.status='DRAFT' then 'REVIEW' else 'PUBLISH' end
    from fi_report r join fi_snapshot s on s.tenant_id=r.tenant_id and s.id=r.snapshot_id join user_account u on u.tenant_id=r.tenant_id and u.id=r.created_by
    where r.tenant_id=:tenantId and r.created_by<>:actorId and r.last_edited_by<>:actorId
     and (:tenantScope or s.hotel_ids <@ array[:scopeIds]::uuid[]) and ((r.status='DRAFT' and :review) or (r.status='REVIEWED' and
   """).append(config).append("))");
  if(table(jdbc,"fa_voucher")&&(has(p,"finance.accounting.review")||has(p,"finance.accounting.post")))sql.append("""
   union all select v.id,'review',case when v.status='DRAFT' then '凭证待独立复核 · ' else '凭证待过账 · ' end||v.summary,h.name,u.display_name,
    (select coalesce(sum(l.debit),0) from fa_voucher_line l where l.tenant_id=v.tenant_id and l.voucher_id=v.id),v.status,v.accounting_date,v.created_at,false,v.version,'ACCOUNTING',case when v.status='DRAFT' then 'REVIEW' else 'POST' end
    from fa_voucher v join fa_book b on b.tenant_id=v.tenant_id and b.id=v.book_id join fa_period period on period.tenant_id=v.tenant_id and period.book_id=v.book_id and period.month=v.month
    join org_unit h on h.tenant_id=b.tenant_id and h.id=b.hotel_id join user_account u on u.tenant_id=v.tenant_id and u.id=v.created_by
    where v.tenant_id=:tenantId and period.status='OPEN' and
   """).append(scope("b","hotel_id")).append(" and (:payroll or not exists(select 1 from fa_source_event e where e.tenant_id=v.tenant_id and e.voucher_id=v.id and (upper(e.source_type) like '%PAYROLL%' or upper(coalesce(e.metadata->>'sourceType','')) like '%PAYROLL%'))) and ((v.status='DRAFT' and v.created_by<>:actorId and ").append(has(p,"finance.accounting.review")).append(") or (v.status='REVIEWED' and ").append(has(p,"finance.accounting.post")).append("))");
  if(table(jdbc,"fc_ledger_change")&&config)sql.append("""
   union all select c.id,'review','科目/映射修订待独立发布',h.name,u.display_name,null::numeric,c.status,null::date,c.created_at,false,c.version,'LEDGER_CHANGE',c.kind
    from fc_ledger_change c join fa_book b on b.tenant_id=c.tenant_id and b.id=c.book_id
    join org_unit h on h.tenant_id=b.tenant_id and h.id=b.hotel_id join user_account u on u.tenant_id=c.tenant_id and u.id=c.created_by
    where c.tenant_id=:tenantId and c.status='DRAFT' and c.created_by<>:actorId and
   """).append(scope("b","hotel_id"));
  if(table(jdbc,"fx_cash_correction"))sql.append(" union all select c.id,'review','资金登记差错待独立复核',h.name,u.display_name,c.amount,c.status,c.accounting_on,c.created_at,false,c.version,'CASH_ERROR','CORRECTION' from fx_cash_correction c join org_unit h on h.tenant_id=c.tenant_id and h.id=c.hotel_id join user_account u on u.tenant_id=c.tenant_id and u.id=c.created_by where c.tenant_id=:tenantId and :review and c.status='REVIEW' and c.reviewer_id=:actorId and c.created_by<>:actorId and ").append(scope("c","hotel_id")).append(" and (c.source_kind<>'OPERATION' or exists(select 1 from fo_document d where d.tenant_id=c.tenant_id and d.id=c.document_id and (d.type<>'PAYROLL' or :payroll) and (d.type<>'TAX_TASK' or :tax)))");
  for(String table:List.of("fb_receivable_adjustment","fb_receivable_recovery","fb_tax_calendar"))if(table(jdbc,table)){String domain=table.equals("fb_tax_calendar")?"TAX_CALENDAR":table.equals("fb_receivable_recovery")?"AR_RECOVERY":"AR_ADJUSTMENT";sql.append(" union all select c.id,'review','专项业务待独立复核',h.name,u.display_name,null::numeric,c.status,null::date,c.created_at,false,c.version,'").append(domain).append("','REVIEW' from ").append(table).append(" c join org_unit h on h.tenant_id=c.tenant_id and h.id=c.hotel_id join user_account u on u.tenant_id=c.tenant_id and u.id=c.created_by where c.tenant_id=:tenantId and :review and c.status='REVIEW' and c.reviewer_id=:actorId and c.created_by<>:actorId and ").append(scope("c","hotel_id"));if(domain.equals("TAX_CALENDAR"))sql.append(" and :tax");}
  if(table(jdbc,"fc_budget_exception"))sql.append(" union all select c.id,'review','预算草稿限额例外待独立复核',h.name,u.display_name,c.ceiling,c.status,null::date,c.created_at,false,c.version,'BUDGET_EXCEPTION','REVIEW' from fc_budget_exception c join org_unit h on h.tenant_id=c.tenant_id and h.id=c.hotel_id join user_account u on u.tenant_id=c.tenant_id and u.id=c.applicant_id where c.tenant_id=:tenantId and :review and c.status='REVIEW' and c.reviewer_id=:actorId and c.valid_until>statement_timestamp() and c.applicant_id<>:actorId and ").append(scope("c","hotel_id")).append(" and (c.source_kind<>'OPERATION' or exists(select 1 from fo_document d where d.tenant_id=c.tenant_id and d.id=c.source_id and (d.type<>'PAYROLL' or :payroll) and (d.type<>'TAX_TASK' or :tax)))");
  if(table(jdbc,"far_policy"))sql.append(" union all select c.id,'review','租赁/待摊政策待独立发布',h.name,u.display_name,null::numeric,c.status,null::date,c.created_at,false,c.version,'ACCRUAL_POLICY','POLICY' from far_policy c join fa_book b on b.tenant_id=c.tenant_id and b.id=c.book_id join org_unit h on h.tenant_id=b.tenant_id and h.id=b.hotel_id join user_account u on u.tenant_id=c.tenant_id and u.id=c.created_by where c.tenant_id=:tenantId and :review and c.status='DRAFT' and c.reviewer_id=:actorId and c.created_by<>:actorId and ").append(scope("b","hotel_id"));
  for(String table:List.of("fcl_register","fcl_bank_explanation"))if(table(jdbc,table))sql.append(" union all select c.id,'review','月结来源或银行未达待独立确认',h.name,u.display_name,null::numeric,c.status,null::date,c.created_at,false,c.version,'CLOSE','").append(table.equals("fcl_register")?"REGISTER":"BANK").append("' from ").append(table).append(" c join fa_book b on b.tenant_id=c.tenant_id and b.id=c.book_id join org_unit h on h.tenant_id=b.tenant_id and h.id=b.hotel_id join user_account u on u.tenant_id=c.tenant_id and u.id=c.created_by where c.tenant_id=:tenantId and :review and c.status='DRAFT' and c.reviewer_id=:actorId and c.created_by<>:actorId and ").append(scope("b","hotel_id"));
  if(table(jdbc,"fac_request")&&has(p,"finance.archive.grant"))sql.append(" union all select c.id,'review','财务档案调阅申请待独立审核','授权档案范围',u.display_name,null::numeric,c.status,null::date,c.created_at,false,c.version,'ARCHIVE_REQUEST','REQUEST' from fac_request c join fac_archive a on a.tenant_id=c.tenant_id and a.id=c.archive_id join user_account u on u.tenant_id=c.tenant_id and u.id=c.applicant_id where c.tenant_id=:tenantId and c.status='PENDING' and c.applicant_id<>:actorId and (:tenantScope or a.hotel_ids <@ array[:scopeIds]::uuid[]) and (:payroll or not a.sensitive_payroll) and ").append(archiveSource("a.source_type","a.source_id",p,table(jdbc,"fd_route"),table(jdbc,"fac_report_source"))).append(" and not exists(select 1 from jsonb_array_elements(coalesce(a.snapshot->'requiredSources','[]'::jsonb)) linked where not ").append(archiveSource("linked->>'type'","cast(linked->>'id' as uuid)",p,table(jdbc,"fd_route"),table(jdbc,"fac_report_source"))).append(")");
  if(table(jdbc,"fi_action_task"))sql.append(" union all select c.id,case when c.status='SUBMITTED' then 'review' else 'work' end,'分析建议跟进 · '||c.title,h.name,u.display_name,null::numeric,c.status,c.due_date,c.created_at,false,c.version,'INSIGHT_ACTION','ACTION' from fi_action_task c join org_unit h on h.tenant_id=c.tenant_id and h.id=c.hotel_id join user_account u on u.tenant_id=c.tenant_id and u.id=c.created_by where c.tenant_id=:tenantId and ").append(scope("c","hotel_id")).append(" and ((c.status in ('OPEN','IN_PROGRESS','REWORK') and c.owner_id=:actorId and (:own or :review or ").append(config).append(")) or (c.status='SUBMITTED' and :review and c.reviewer_id=:actorId and c.owner_id<>:actorId and c.submitted_by<>:actorId))");
  if(table(jdbc,"fs_invoice_release"))sql.append(" union all select c.id,'review','采购发票误选释放待独立复核',h.name,u.display_name,null::numeric,c.status,null::date,c.created_at,false,c.version,'SUPPLY_INVOICE_RELEASE','RELEASE' from fs_invoice_release c join fs_recognition r on r.tenant_id=c.tenant_id and r.id=c.recognition_id join org_unit h on h.tenant_id=r.tenant_id and h.id=r.hotel_id join user_account u on u.tenant_id=c.tenant_id and u.id=c.applicant_id where c.tenant_id=:tenantId and :review and c.status='REVIEW' and c.reviewer_id=:actorId and c.applicant_id<>:actorId and ").append(scope("r","hotel_id"));
  if(table(jdbc,"fd_delegation")&&config)sql.append(" union all select c.id,'review','限时审批代理待独立发布',h.name,u.display_name,null::numeric,c.status,null::date,c.created_at,false,c.version,'DELEGATION','PUBLISH' from fd_delegation c join org_unit h on h.tenant_id=c.tenant_id and h.id=c.hotel_id join user_account u on u.tenant_id=c.tenant_id and u.id=c.created_by where c.tenant_id=:tenantId and c.status='DRAFT' and c.created_by<>:actorId and c.deputy_id<>:actorId and c.valid_until>statement_timestamp() and ").append(scope("c","hotel_id"));
  if(table(jdbc,"fs_asset_gain")&&financialRead&&has(p,"finance.accounting.write"))sql.append(" union all select c.id,'review','实物盘盈估值待独立确认',h.name,u.display_name,c.value,c.status,c.accounting_on,c.created_at,false,c.version,'ASSET_GAIN','ASSET_GAIN' from fs_asset_gain c join org_unit h on h.tenant_id=c.tenant_id and h.id=c.hotel_id join user_account u on u.tenant_id=c.tenant_id and u.id=c.applicant_id where c.tenant_id=:tenantId and :review and c.status='PENDING' and c.reviewer_id=:actorId and c.applicant_id<>:actorId and ").append(scope("c","hotel_id"));
  if(table(jdbc,"fb_payroll_batch"))sql.append(" union all select c.id,'payment','已确认工资待实际支付 · '||to_char(c.month,'YYYY-MM'),h.name,u.display_name,c.net_amount-coalesce(paid.total,0),c.status,c.month,c.created_at,false,c.version,'FINANCE_BUSINESS','PAYROLL' from fb_payroll_batch c join org_unit h on h.tenant_id=c.tenant_id and h.id=c.hotel_id join user_account u on u.tenant_id=c.tenant_id and u.id=c.created_by left join lateral(select sum(fb_cash_effective_amount(x.tenant_id,'PAYROLL',x.id,x.amount,'9999-12-31'::date)) total from fb_payroll_payment x join fb_payroll_line l on l.tenant_id=x.tenant_id and l.id=x.line_id where l.tenant_id=c.tenant_id and l.batch_id=c.id) paid on true where c.tenant_id=:tenantId and :pay and :payroll and c.status='CONFIRMED' and c.cashier_id=:actorId and c.created_by<>:actorId and c.net_amount>coalesce(paid.total,0) and ").append(scope("c","hotel_id"));
  if(table(jdbc,"ft_input_basis"))sql.append(" union all select c.id,'review','进项原件税额待独立确认',h.name,u.display_name,c.tax_amount,c.status,null::date,c.created_at,false,c.version,'INPUT_BASIS','BASIS' from ft_input_basis c join finance_store_config cfg on cfg.tenant_id=c.tenant_id and cfg.hotel_id=c.hotel_id and cfg.company_id=c.company_id and cfg.enabled and cfg.workflow_version=2 join org_unit h on h.tenant_id=c.tenant_id and h.id=c.hotel_id join user_account u on u.tenant_id=c.tenant_id and u.id=c.created_by where c.tenant_id=:tenantId and :tax and :review and c.status='REVIEW' and c.reviewer_id=:actorId and :actorId in(cfg.finance_account_id,cfg.director_account_id) and c.created_by<>:actorId and ").append(scope("c","hotel_id"));
  if(table(jdbc,"ft_tax_accrual"))sql.append(" union all select c.id,case when c.status='REVIEW' then 'review' else 'payment' end,'税费计提/实缴当前节点',h.name,u.display_name,c.amount-ft_tax_paid_amount(c.tenant_id,c.id,'9999-12-31'::date),c.status,c.accounting_on,c.created_at,false,c.version,'TAX_ACCRUAL','ACCRUAL' from ft_tax_accrual c join fb_tax_return actual_return on actual_return.tenant_id=c.tenant_id and actual_return.id=c.return_id join finance_store_config cfg on cfg.tenant_id=c.tenant_id and cfg.hotel_id=c.hotel_id and cfg.company_id=c.company_id and cfg.enabled and cfg.workflow_version=2 join org_unit h on h.tenant_id=c.tenant_id and h.id=c.hotel_id join user_account u on u.tenant_id=c.tenant_id and u.id=c.created_by where c.tenant_id=:tenantId and :tax and "+FinanceTaxScope.readableSql("actual_return")+" and ((c.status='REVIEW' and :review and c.reviewer_id=:actorId and :actorId in(cfg.finance_account_id,cfg.director_account_id) and c.created_by<>:actorId) or (c.status='CONFIRMED' and :pay and c.cashier_id=:actorId and cfg.cashier_account_id=:actorId and c.created_by<>:actorId and c.amount>ft_tax_paid_amount(c.tenant_id,c.id,'9999-12-31'::date) and exists(select 1 from fa_source_event e join fa_voucher v on v.tenant_id=e.tenant_id and v.id=e.voucher_id where e.tenant_id=c.tenant_id and e.source_type='FB_TAX_ACCRUAL' and e.source_id=c.id and e.status='POSTED' and v.status='POSTED' and v.reversed_by_id is null))) and ").append(scope("c","hotel_id"));
  if(table(jdbc,"fb_tax_calendar"))sql.append(" union all select c.id,'work','税务义务待归档 · '||c.title,h.name,u.display_name,null::numeric,c.status,c.due_on,c.created_at,false,c.version,'TAX_CALENDAR','OBLIGATION' from fb_tax_calendar c join org_unit h on h.tenant_id=c.tenant_id and h.id=c.hotel_id join user_account u on u.tenant_id=c.tenant_id and u.id=c.created_by join finance_store_config cfg on cfg.tenant_id=c.tenant_id and cfg.hotel_id=c.hotel_id and cfg.company_id=c.company_id where c.tenant_id=:tenantId and :tax and :review and c.status='ACTIVE' and cfg.enabled and cfg.workflow_version=2 and c.reviewer_id=:actorId and :actorId in(cfg.finance_account_id,cfg.director_account_id) and not exists(select 1 from fb_tax_calendar_link link join fb_tax_receipt receipt on receipt.tenant_id=link.tenant_id and receipt.return_id=link.return_id join fb_attachment original on original.tenant_id=receipt.tenant_id and original.id=receipt.attachment_id and original.domain='TAX' and original.scan_status='CLEAN' where link.tenant_id=c.tenant_id and link.calendar_id=c.id and receipt.kind=c.obligation"+(table(jdbc,"ft_tax_accrual")?" and (c.obligation='FILING' or exists(select 1 from ft_tax_accrual actual_tax where actual_tax.tenant_id=c.tenant_id and actual_tax.return_id=link.return_id and actual_tax.status='CONFIRMED' and ft_tax_paid_amount(actual_tax.tenant_id,actual_tax.id,'9999-12-31'::date)>=actual_tax.amount))":"")+") and ").append(scope("c","hotel_id"));
  if(table(jdbc,"fx_cash_correction")){
   String net="fx_operation_action_amount(c.tenant_id,c.id,'PAYMENT','9999-12-31'::date)-fx_operation_action_amount(c.tenant_id,c.id,'REFUND','9999-12-31'::date)-fx_operation_action_amount(c.tenant_id,c.id,'REPAYMENT','9999-12-31'::date)-fx_operation_action_amount(c.tenant_id,c.id,'WRITEOFF','9999-12-31'::date)";
   sql.append(" union all select c.id,'work','已发放借款逾期待清理 · '||c.title,h.name,u.display_name,").append(net).append(",c.status,cast(c.details->>'repayBy' as date),c.created_at,false,c.version,'LOAN_OVERDUE','LOAN' from fo_document c join org_unit h on h.tenant_id=c.tenant_id and h.id=c.hotel_id join user_account u on u.tenant_id=c.tenant_id and u.id=c.applicant_id where c.tenant_id=:tenantId and :review and c.type='LOAN' and c.status='APPROVED' and c.approval_route @> jsonb_build_array(cast(:actorId as text)) and cast(c.details->>'repayBy' as date)<(select (statement_timestamp() at time zone t.timezone)::date from tenant t where t.id=c.tenant_id) and (").append(net).append(")>0 and ").append(scope("c","hotel_id"));
  }
  return " "+sql;
 }
}
